      hazel: { name: 'Hazel', period: 'Aug 5 – Sep 1', keywords: ['Wisdom', 'Analysis', 'Intuition'], nature: 'The tree of wisdom. Analytical, you see the essence of things.', love: 'Drawn to people you can have smart conversations with.', advice: 'What you learn always becomes your strength.' },
      vine: { name: 'Vine', period: 'Sep 2 – Sep 29', keywords: ['Harmony', 'Balance', 'Elegance'], nature: 'The vine of harvest season. Balanced and refined, you love beautiful things.', love: 'You seek a calm, refined relationship.', advice: 'When unsure, choose what brings you peace.' },
